"""Telegram Mini App — the client's live trading terminal inside Telegram.

Served by the bot's own HTTP server at /app. The page authenticates itself by
sending Telegram's signed initData with every API call; validate() checks the
HMAC per https://core.telegram.org/bots/webapps#validating-data-received so a
client can only ever see THEIR OWN account."""
import hmac
import json
import hashlib
from urllib.parse import parse_qsl


def validate(init_data: str, bot_token: str):
    """Return the Telegram user dict if initData is authentic, else None."""
    try:
        pairs = dict(parse_qsl(init_data, keep_blank_values=True))
        their_hash = pairs.pop("hash", "")
        dcs = "\n".join(f"{k}={v}" for k, v in sorted(pairs.items()))
        secret = hmac.new(b"WebAppData", bot_token.encode(), hashlib.sha256).digest()
        calc = hmac.new(secret, dcs.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(calc, their_hash):
            return None
        return json.loads(pairs.get("user", "{}"))
    except Exception:
        return None


HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no">\n<title>Apex Terminal</title>\n<script src="https://telegram.org/js/telegram-web-app.js"></script>\n<script src="https://unpkg.com/lightweight-charts@4.1.3/dist/lightweight-charts.standalone.production.js"></script>\n<style>\n:root{--bg:#07090f;--card:rgba(255,255,255,.045);--line:rgba(255,255,255,.08);\n  --t0:#eef1f6;--t1:#9aa3b2;--t2:#5b6472;--up:#2fd575;--dn:#ff4560;--acc:#ff2d4f;--gold:#f5b544}\n*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nbody{background:var(--bg);color:var(--t0);font-family:-apple-system,\'SF Pro Display\',system-ui,sans-serif;\n  overflow-x:hidden;padding-bottom:30px}\nbody::before{content:\'\';position:fixed;inset:0;pointer-events:none;z-index:0;\n  background:radial-gradient(70% 32% at 50% -4%,rgba(255,45,79,.16),transparent 70%)}\n.wrap{position:relative;z-index:1}\n@keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\n.rise{animation:rise .5s cubic-bezier(.22,.61,.36,1) both}\n/* HERO */\n#hero{padding:18px 16px 14px}\n#brand{font-size:10.5px;font-weight:800;letter-spacing:.28em;color:var(--t2);margin-bottom:10px}\n#brand b{color:var(--acc)}\n#balRow{display:flex;align-items:flex-end;justify-content:space-between;gap:10px}\n#balV{font-size:34px;font-weight:800;letter-spacing:-.02em;font-variant-numeric:tabular-nums}\n#dayChip{font-size:13px;font-weight:700;border-radius:9px;padding:6px 10px;background:rgba(47,213,117,.12);color:var(--up)}\n#dayChip.neg{background:rgba(255,69,96,.12);color:var(--dn)}\n#badges{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}\n.badge{font-size:10.5px;font-weight:700;letter-spacing:.03em;border:1px solid var(--line);\n  background:var(--card);border-radius:100px;padding:5px 10px;color:var(--t1);backdrop-filter:blur(10px)}\n.badge.hot{color:#ffd7de;border-color:rgba(255,45,79,.35);background:rgba(255,45,79,.10)}\n/* STAT TILES */\n#tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:4px 16px 0}\n.tile{background:linear-gradient(165deg,rgba(255,255,255,.06),rgba(255,255,255,.02));\n  border:1px solid var(--line);border-radius:14px;padding:10px 8px;text-align:center;backdrop-filter:blur(12px)}\n.tile b{display:block;font-size:15.5px;font-weight:800;font-variant-numeric:tabular-nums}\n.tile span{display:block;font-size:8.5px;font-weight:700;letter-spacing:.09em;color:var(--t2);\n  text-transform:uppercase;margin-top:3px}\n/* CHART CARD */\n.card{margin:12px 16px 0;background:linear-gradient(165deg,rgba(255,255,255,.05),rgba(255,255,255,.015));\n  border:1px solid var(--line);border-radius:18px;overflow:hidden;backdrop-filter:blur(14px)}\n.card-h{display:flex;align-items:center;justify-content:space-between;padding:12px 14px 8px}\n.card-h b{font-size:13.5px;font-weight:800}\n.card-h span{font-size:10.5px;color:var(--t2);font-weight:600}\n#chart{height:42vh}\n#eqChart{height:30vh;display:none}\n#pos{margin:10px 14px 12px;padding:11px 12px;border:1px solid var(--line);border-radius:12px;\n  font-size:13px;display:none;background:rgba(0,0,0,.25)}\n#pos .lg{font-weight:800}\n#pos .grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin-top:8px;font-size:11.5px;color:var(--t1)}\n#pos .grid b{display:block;color:var(--t0);font-size:12.5px;font-variant-numeric:tabular-nums}\n.pnl-up{color:var(--up)} .pnl-dn{color:var(--dn)}\n/* TABS */\n#tabs{display:flex;gap:6px;margin:14px 16px 10px}\n.tab{flex:1;text-align:center;padding:10px 4px;background:var(--card);border:1px solid var(--line);\n  border-radius:12px;font-size:11.5px;font-weight:700;color:var(--t1);transition:all .25s;backdrop-filter:blur(10px)}\n.tab.on{color:#fff;border-color:rgba(255,45,79,.45);background:rgba(255,45,79,.13)}\n.panel{margin:0 16px;display:none}\n.panel.on{display:block;animation:rise .35s both}\n.item{padding:11px 2px;border-bottom:1px solid var(--line);font-size:13px;line-height:1.5}\n.item:last-child{border-bottom:none}\n.item .sub{color:var(--t1);font-size:11px;margin-top:2px}\n.chip{display:inline-block;font-size:9.5px;font-weight:800;border-radius:5px;padding:2px 6px;\n  background:rgba(245,181,68,.14);color:var(--gold);margin-right:6px;letter-spacing:.05em}\n.chip.red{background:rgba(255,45,79,.14);color:#ff97a8}\n.empty{color:var(--t2);font-size:12.5px;padding:16px 2px;text-align:center}\n/* performance detail rows */\n.kv{display:flex;justify-content:space-between;padding:9px 2px;border-bottom:1px solid var(--line);font-size:13px}\n.kv:last-child{border-bottom:none}\n.kv span{color:var(--t1)} .kv b{font-variant-numeric:tabular-nums}\n#jSwitch{display:flex;gap:6px;margin-bottom:10px}\n#jSwitch div{flex:1;text-align:center;font-size:11px;font-weight:700;padding:7px;border-radius:9px;\n  border:1px solid var(--line);color:var(--t1);background:var(--card)}\n#jSwitch div.on{color:#fff;background:rgba(255,45,79,.13);border-color:rgba(255,45,79,.4)}\n#err{position:fixed;bottom:10px;left:16px;right:16px;background:rgba(255,69,96,.14);border:1px solid rgba(255,69,96,.4);\n  color:#ffb4be;font-size:11.5px;padding:8px 12px;border-radius:10px;display:none;z-index:9}\n</style>\n</head>\n<body>\n<div class="wrap">\n  <div id="hero" class="rise">\n    <div id="brand">APEX <b>TERMINAL</b></div>\n    <div id="balRow">\n      <div id="balV">$ —</div>\n      <div id="dayChip">today —</div>\n    </div>\n    <div id="badges"></div>\n  </div>\n\n  <div id="tiles" class="rise">\n    <div class="tile"><b id="tWr">—</b><span>Win rate</span></div>\n    <div class="tile"><b id="tPf">—</b><span>Profit factor</span></div>\n    <div class="tile"><b id="tDd">—</b><span>Max DD</span></div>\n    <div class="tile"><b id="tSk">—</b><span>Rejected today</span></div>\n  </div>\n\n  <div class="card rise">\n    <div class="card-h"><b id="cSym">—</b><span id="cMeta">loading…</span></div>\n    <div id="chart"></div>\n    <div id="eqChart"></div>\n    <div id="pos"></div>\n  </div>\n\n  <div id="tabs" class="rise">\n    <div class="tab on" data-p="chart">📈 Chart</div>\n    <div class="tab" data-p="perf">💰 Stats</div>\n    <div class="tab" data-p="news">📰 News</div>\n    <div class="tab" data-p="journal">🧾 Journal</div>\n  </div>\n  <div class="panel on" id="p-chart"></div>\n  <div class="panel" id="p-perf"><div class="empty">Loading…</div></div>\n  <div class="panel" id="p-news"><div class="empty">Loading events…</div></div>\n  <div class="panel" id="p-journal">\n    <div id="jSwitch"><div class="on" data-j="trades">Trades</div><div data-j="skips">Rejected setups</div></div>\n    <div id="jTrades"><div class="empty">No trades yet.</div></div>\n    <div id="jSkips" style="display:none"><div class="empty">Nothing rejected yet today.</div></div>\n  </div>\n</div>\n<div id="err"></div>\n<script>\nconst tg = window.Telegram && Telegram.WebApp; if(tg){tg.ready();tg.expand();tg.setBackgroundColor(\'#07090f\');}\nconst initData = tg ? tg.initData : \'\';\nconst mk = (el,opts)=>LightweightCharts.createChart(el,Object.assign({\n  layout:{background:{color:\'transparent\'},textColor:\'#5b6472\',fontSize:10},\n  grid:{vertLines:{color:\'rgba(255,255,255,.04)\'},horzLines:{color:\'rgba(255,255,255,.04)\'}},\n  timeScale:{timeVisible:true,secondsVisible:false,borderColor:\'rgba(255,255,255,.08)\'},\n  rightPriceScale:{borderColor:\'rgba(255,255,255,.08)\'},crosshair:{mode:1}},opts||{}));\nconst chartEl=document.getElementById(\'chart\'), eqEl=document.getElementById(\'eqChart\');\nconst chart=mk(chartEl);\nconst series=chart.addCandlestickSeries({upColor:\'#2fd575\',downColor:\'#ff4560\',\n  borderUpColor:\'#2fd575\',borderDownColor:\'#ff4560\',wickUpColor:\'#2fd575\',wickDownColor:\'#ff4560\'});\nconst eqChart=mk(eqEl,{timeScale:{timeVisible:false}});\nconst eqSeries=eqChart.addAreaSeries({lineColor:\'#ff2d4f\',lineWidth:2,\n  topColor:\'rgba(255,45,79,.25)\',bottomColor:\'rgba(255,45,79,0)\'});\nnew ResizeObserver(()=>{chart.applyOptions({width:chartEl.clientWidth,height:chartEl.clientHeight});\n  eqChart.applyOptions({width:eqEl.clientWidth,height:eqEl.clientHeight});}).observe(chartEl);\nlet lines=[];\nfunction setLines(pos){lines.forEach(l=>series.removePriceLine(l));lines=[];if(!pos)return;\n  const mkl=(p,c,t)=>{if(p)lines.push(series.createPriceLine({price:p,color:c,lineWidth:1,lineStyle:2,title:t}))};\n  mkl(pos.entryPrice,\'#eef1f6\',\'ENTRY\');mkl(pos.stopLoss||pos.sl,\'#ff4560\',\'SL\');mkl(pos.takeProfit||pos.tp,\'#2fd575\',\'TP\');}\ndocument.querySelectorAll(\'.tab\').forEach(t=>t.onclick=()=>{\n  document.querySelectorAll(\'.tab\').forEach(x=>x.classList.remove(\'on\'));\n  document.querySelectorAll(\'.panel\').forEach(x=>x.classList.remove(\'on\'));\n  t.classList.add(\'on\');document.getElementById(\'p-\'+t.dataset.p).classList.add(\'on\');\n  const perf = t.dataset.p===\'perf\';\n  chartEl.style.display = perf?\'none\':\'block\';\n  eqEl.style.display = perf?\'block\':\'none\';\n  document.getElementById(\'cSym\').textContent = perf?\'Equity curve\':lastSym;\n  setTimeout(()=>{eqChart.timeScale().fitContent();},50);});\ndocument.querySelectorAll(\'#jSwitch div\').forEach(d=>d.onclick=()=>{\n  document.querySelectorAll(\'#jSwitch div\').forEach(x=>x.classList.remove(\'on\'));d.classList.add(\'on\');\n  document.getElementById(\'jTrades\').style.display=d.dataset.j===\'trades\'?\'block\':\'none\';\n  document.getElementById(\'jSkips\').style.display=d.dataset.j===\'skips\'?\'block\':\'none\';});\nconst esc=s=>String(s||\'\').replace(/[<>&]/g,c=>({\'<\':\'&lt;\',\'>\':\'&gt;\',\'&\':\'&amp;\'}[c]));\nconst money=v=>(v>=0?\'+$\':\'−$\')+Math.abs(v).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});\nlet first=true,lastSym=\'—\';\nasync function refresh(){\n try{\n  const r=await fetch(\'/api/app/data?init=\'+encodeURIComponent(initData));\n  if(!r.ok)throw new Error(\'HTTP \'+r.status);\n  const d=await r.json();\n  document.getElementById(\'err\').style.display=\'none\';\n  lastSym=d.symbol.replace(\'_\',\'/\');\n  if(!document.querySelector(\'.tab[data-p="perf"]\').classList.contains(\'on\'))\n    document.getElementById(\'cSym\').textContent=lastSym;\n  document.getElementById(\'cMeta\').textContent=d.timeframe+\' · \'+(d.broker||\'\');\n  document.getElementById(\'balV\').textContent=\'$\'+(d.balance||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});\n  const st=d.stats||{},td=st.today||{};\n  const chip=document.getElementById(\'dayChip\');\n  chip.textContent=\'today \'+money(td.netPnl||0)+\' · \'+(td.trades||0)+\' trades\';\n  chip.className=(td.netPnl||0)<0?\'neg\':\'\';\n  const badges=[];\n  badges.push({t:d.mode||\'\',hot:(d.mode||\'\').includes(\'REAL\')});\n  badges.push({t:\'🎯 \'+(d.strategy||\'\')});\n  if(d.regime&&d.regime.label)badges.push({t:\'🌊 \'+d.regime.regime+\' (\'+d.regime.vol_ratio+\'×)\'});\n  if(d.sessions&&d.sessions.length)badges.push({t:\'🕐 \'+d.sessions.join(\' + \')});\n  document.getElementById(\'badges\').innerHTML=badges.map(b=>\'<span class="badge\'+(b.hot?\' hot\':\'\')+\'">\'+esc(b.t)+\'</span>\').join(\'\');\n  document.getElementById(\'tWr\').textContent=st.winRate!=null?st.winRate.toFixed(0)+\'%\':\'—\';\n  document.getElementById(\'tPf\').textContent=st.profitFactor!=null?st.profitFactor:\'—\';\n  document.getElementById(\'tDd\').textContent=st.maxDrawdownPct!=null?st.maxDrawdownPct.toFixed(1)+\'%\':\'—\';\n  document.getElementById(\'tSk\').textContent=td.skips!=null?td.skips:\'0\';\n  if(d.candles&&d.candles.length){\n    series.setData(d.candles);if(first){chart.timeScale().fitContent();first=false;}}\n  if(d.equity&&d.equity.length){\n    eqSeries.setData(d.equity.map((p,i)=>({time:i,value:p.value})));}\n  setLines(d.position);\n  const pos=document.getElementById(\'pos\');\n  if(d.position){const p=d.position,dir=p.side===\'BUY\'?\'🟢 LONG\':\'🔴 SHORT\';\n    pos.style.display=\'block\';\n    pos.innerHTML=\'<span class="lg">\'+dir+\' \'+esc(lastSym)+\'</span>\'+\n      (p.pnlPips!=null?\' · <span class="\'+(p.pnlPips>=0?\'pnl-up\':\'pnl-dn\')+\'">\'+(p.pnlPips>=0?\'+\':\'\')+p.pnlPips+\' pips</span>\':\'\')+\n      \'<div class="grid"><div>Entry<b>\'+(p.entryPrice||\'—\')+\'</b></div>\'+\n      \'<div>Stop<b>\'+((p.stopLoss||p.sl)||\'—\')+\'</b></div>\'+\n      \'<div>Target<b>\'+((p.takeProfit||p.tp)||\'—\')+\'</b></div></div>\';\n  }else pos.style.display=\'none\';\n  const perf=document.getElementById(\'p-perf\');\n  if(st.trades){\n    perf.innerHTML=\n      \'<div class="kv"><span>Closed trades</span><b>\'+st.trades+\' (\'+st.wins+\'W / \'+st.losses+\'L)</b></div>\'+\n      \'<div class="kv"><span>Net P&L</span><b class="\'+(st.netPnl>=0?\'pnl-up\':\'pnl-dn\')+\'">\'+money(st.netPnl)+\'</b></div>\'+\n      \'<div class="kv"><span>Profit factor</span><b>\'+(st.profitFactor!=null?st.profitFactor:\'—\')+\'</b></div>\'+\n      \'<div class="kv"><span>Average win / loss</span><b>\'+money(st.avgWin)+\' / \'+money(st.avgLoss)+\'</b></div>\'+\n      \'<div class="kv"><span>Best / worst trade</span><b>\'+money(st.best)+\' / \'+money(st.worst)+\'</b></div>\'+\n      \'<div class="kv"><span>Max drawdown</span><b>\'+st.maxDrawdownPct.toFixed(1)+\'%</b></div>\';\n  }else perf.innerHTML=\'<div class="empty">No closed trades yet — stats build as the bot works.</div>\';\n  const nv=document.getElementById(\'p-news\');\n  if(d.events&&d.events.length){\n    nv.innerHTML=d.events.map(e=>{const h=Math.floor(e.in_min/60),m=e.in_min%60;\n      return \'<div class="item"><span class="chip">\'+esc(e.currency)+\'</span><b>\'+esc(e.title)+\'</b>\'+\n        \'<div class="sub">in \'+(h?h+\'h \':\'\')+m+\'m · high impact — the bot stands aside around it</div></div>\';}).join(\'\');\n  }else nv.innerHTML=\'<div class="empty">No high-impact events in the next 24h — clear runway. ✅</div>\';\n  const jt=document.getElementById(\'jTrades\');\n  if(d.trades&&d.trades.length){\n    jt.innerHTML=d.trades.map(t=>{const pnl=t.netPnl;\n      return \'<div class="item"><b>\'+esc(t.action||\'\')+\'</b> \'+esc((t.symbol||\'\').replace(\'_\',\'/\'))+\n        (t.price?\' @ \'+t.price:\'\')+(pnl!=null?\' · <span class="\'+(pnl>=0?\'pnl-up\':\'pnl-dn\')+\'">\'+money(pnl)+\'</span>\':\'\')+\n        \'<div class="sub">\'+esc(t.time||\'\')+(t.reasoning?\' — \'+esc(t.reasoning):\'\')+\'</div></div>\';}).join(\'\');}\n  const js=document.getElementById(\'jSkips\');\n  if(d.skips&&d.skips.length){\n    js.innerHTML=d.skips.map(k=>\'<div class="item"><span class="chip red">SKIP</span>\'+esc(k.reason)+\n      \'<div class="sub">\'+esc(k.time||\'\')+\'</div></div>\').join(\'\');}\n }catch(e){const el=document.getElementById(\'err\');el.style.display=\'block\';el.textContent=\'Reconnecting… (\'+e.message+\')\';}\n}\nrefresh();setInterval(refresh,6000);\n</script>\n</body>\n</html>'
